// Writes an empty asset manifest ({"clips":{},"stills":{}}) for every src/manifest*.json that
// src/assets.ts imports and that does not exist yet. The manifests are generated by the asset
// pipeline (npm run assets) and git-ignored, so on a fresh clone this lets the project
// type-check and bundle before the assets are rendered. Never touches an existing manifest.
// Runs on `npm install` (postinstall).
//
//   node scripts/ensure-manifests.mjs
import fs from 'node:fs';
import path from 'node:path';
import {root} from './lib/remotion.mjs';

const src = path.join(root, 'src');
const imports = fs
  .readFileSync(path.join(src, 'assets.ts'), 'utf8')
  .matchAll(/from '\.\/(manifest[\w.-]*\.json)'/g);
for (const [, file] of imports) {
  const p = path.join(src, file);
  if (fs.existsSync(p)) continue;
  fs.writeFileSync(p, '{"clips":{},"stills":{}}\n');
  console.log(`wrote an empty src/${file} (render the assets with npm run assets)`);
}
